-- Contenu éditorial de Peyrissac (sans comptes, sessions ni préférences).
-- À appliquer APRÈS `npm run payload migrate` (le schéma doit exister) :
--   psql "$DATABASE_URL" -f restore/contenu.sql
-- Remplace tout le contenu existant ; les utilisateurs ne sont pas touchés.
BEGIN;
TRUNCATE public.archives, public.familles, public.familles_marques, public.informations, public.interviews, public.interviews_echanges, public.media RESTART IDENTITY CASCADE;








SELECT pg_catalog.setval('public.archives_id_seq', 6, true);
SELECT pg_catalog.setval('public.familles_id_seq', 7, true);
SELECT pg_catalog.setval('public.informations_id_seq', 1, true);
SELECT pg_catalog.setval('public.interviews_id_seq', 20, true);
SELECT pg_catalog.setval('public.media_id_seq', 7, true);
COMMIT;
